import React,{useEffect,useRef,useState} from 'react';

/** Coordinate-neutral track controls; callers own mutations and ordering. */
export function TimelineTrackHeader({track,count,busy=false,onRename,onSettings,dragHandlers,scale=1}){
 const safeScale=Math.max(.125,Math.min(2,Number.isFinite(scale)?scale:1)),headerHeight=32*safeScale,compact=safeScale<.75;
 const [name,setName]=useState(track.name),[saving,setSaving]=useState(false),[error,setError]=useState('');
 const skip=useRef(false),lock=useRef(false),alive=useRef(true);
 useEffect(()=>{alive.current=true;return()=>{alive.current=false;};},[]);
 useEffect(()=>{setName(track.name);setError('');},[track.id,track.name]);
 const submit=async()=>{if(skip.current){skip.current=false;return;}const next=name.trim();if(!next){setName(track.name);return;}if(next===track.name||busy||lock.current||!onRename)return;lock.current=true;setSaving(true);setError('');try{if(await onRename(next)===false&&alive.current)setError('尚未保存，请重试');}catch{if(alive.current)setError('尚未保存，请重试');}finally{lock.current=false;if(alive.current)setSaving(false);}};
 return <header className={`timeline-track-header ${compact?'is-compact':''}`} style={{'--track-header-height':`${headerHeight}px`,'--track-header-scale':safeScale}} data-track-control><style>{styles}</style>
 {!compact&&dragHandlers&&<button type="button" className="timeline-track-grip" aria-label={`拖动轨道：${track.name}`} title="拖动排序；空格拾起，方向键移动，Enter 放下，Esc 取消" disabled={busy||saving} {...dragHandlers}>⠿</button>}
 <i aria-hidden="true" style={{background:track.color}}/>
 {compact&&onSettings?<button type="button" className="timeline-track-compact" aria-label={`设置轨道：${track.name}`} title={track.name} disabled={busy||saving} onClick={onSettings}>{track.name}<span aria-hidden="true">⌄</span></button>:!compact&&onRename?<input aria-label={`轨道名称：${track.name}`} title="直接编辑轨道名称；Enter 保存，Esc 取消" maxLength={80} value={name} disabled={busy||saving} onChange={e=>setName(e.target.value)} onBlur={submit} onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();e.currentTarget.blur();}if(e.key==='Escape'){e.preventDefault();e.stopPropagation();skip.current=true;setName(track.name);setError('');e.currentTarget.blur();}}}/>:<strong>{track.name}</strong>}
 {!compact&&count!=null&&<small>{count} 条剧情</small>}
 {!compact&&onSettings&&<button type="button" className="timeline-track-settings" aria-label={`设置轨道：${track.name}`} title="轨道设置" disabled={busy||saving} onClick={onSettings}>···</button>}
 {error&&<span className="timeline-track-error" role="alert">{error}<button type="button" disabled={busy||saving} onClick={submit}>重试</button></span>}
 </header>;
}
const styles=`.timeline-track-header{position:sticky;left:8px;z-index:6;display:flex;align-items:center;gap:5px;width:max-content;max-width:calc(100% - 16px);height:var(--track-header-height,32px);box-sizing:border-box;padding:0 6px;background:var(--cg-paper);color:var(--cg-muted);border:0;border-radius:5px}.timeline-track-header>i{width:7px;height:7px;border-radius:50%;flex:none}.cuigengji .timeline-track-header>input{width:110px;min-width:45px;max-width:40vw;border:1px solid transparent!important;background:transparent!important;padding:3px!important;border-radius:4px;font-size:calc(12px * var(--track-header-scale,1));height:100%;box-sizing:border-box;min-height:0!important;color:var(--cg-ink)}.cuigengji .timeline-track-header>input:hover,.cuigengji .timeline-track-header>input:focus{border-color:var(--cg-line)!important}.timeline-track-header>strong{font-size:12px}.timeline-track-header>small{font-size:10px;white-space:nowrap}.cuigengji .timeline-track-header>button{min-height:0!important;height:var(--track-header-height);max-height:var(--track-header-height);padding:0 5px!important;border:0;background:transparent;font-size:16px}.timeline-track-grip{touch-action:none;cursor:grab}.timeline-track-error{position:absolute;top:100%;left:0;z-index:15;background:var(--cg-paper);border:1px solid var(--cg-line);padding:5px;font-size:11px;white-space:nowrap}.cuigengji .timeline-track-header.is-compact>button{height:var(--track-header-height);min-height:var(--track-header-height);max-height:var(--track-header-height);min-width:calc(88px * var(--track-header-scale));max-width:calc(180px * var(--track-header-scale));display:flex;align-items:center;justify-content:space-between;gap:3px;font-size:calc(11px * var(--track-header-scale));line-height:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.timeline-track-header.is-compact{gap:4px;padding:0 4px}.timeline-track-header.is-compact>i{width:calc(7px * var(--track-header-scale));height:calc(7px * var(--track-header-scale))}.timeline-track-header.is-compact>strong{font-size:calc(12px * var(--track-header-scale));line-height:1}`;
